"Abstand Anfang / Ende":"Odsunięcie początek / koniec",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Odsunięcie początku / końca zamienia kołnierz w kołnierz częściowy. Pozostałe zamknięte profile w szkicu stają się wycięciami w płycie. Otwory i okna w kołnierzu: środek wzdłuż krawędzi (przy krawędzi zakrzywionej wzdłuż łuku), środek od końca gięcia, rozmiar – są widoczne także w rozwinięciu. Jeśli krawędź zakrzywiona przechodzi bez załamania w sąsiednią krawędź i obie mają kołnierz o tym samym kącie gięcia, kołnierze przechodzą jeden w drugi bez wycięcia odciążającego. „Kontur ze szkicu” wycina z kołnierza zamknięte profile szkicu: jego oś X biegnie wzdłuż krawędzi, oś Y w głąb kołnierza, a punkt zerowy leży na początku krawędzi, na końcu gięcia (można go przesuwać).",
