"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Wybierz wszystkie ściany, które mają zniknąć (dla kieszeni ściany i dno, dla otworu jego ścianę, dla zaokrąglenia powierzchnię zaokrąglenia). Sąsiednie ściany są wydłużane przez powstałą lukę. Krok jest przeliczany przy zmianach bryły; przy pierwszym użyciu ładuje się w tym celu pełne jądro geometryczne (kilka sekund).",
