"Das Bild konnte nicht gelesen werden.":"Nie można odczytać obrazu.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Obraz leży jako wzorzec na płaszczyźnie. Następnie ustaw rozmiar, położenie, obrót i krycie w oknie właściwości (np. szerokość według znanego wymiaru).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Wynik jądra geometrii jest nieczytelny",
"Das Ergebnis konnte nicht geschrieben werden":"Nie można zapisać wyniku",
"Das Maß muss größer als 0 sein.":"Wymiar musi być większy niż 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Siatka pozostaje siatką trójkątów (nie B-Rep). Edycja w sekcji SIATKA: Napraw, Zredukuj, Wygładź, Przekrój płaszczyzną … Strategie frezowania 3D w module Wytwarzanie mogą ją obrabiać bezpośrednio.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"Siatka ma trójkątów: {0}. Każdy stanie się ścianą bryły – trwa to długo i spowalnia bryłę. Zwykle lepiej wcześniej użyć „Zredukuj”.\n\nMimo to przekształcić?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"Siatka nie jest zamknięta. Najpierw wykonaj „Napraw” – bryła wymaga zamkniętej powłoki.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"Siatka rozciąga się w Z od {0} do {1} mm, w X od {2} do {3} mm, w Y od {4} do {5} mm. Punkty odbiegające od prostej o mniej niż tolerancja są usuwane.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profil nie może przecinać osi. Jako oś może posłużyć otwarta linia w szkicu.",
"Das Profil mit den jetzigen Werten überschreiben":"Nadpisz profil bieżącymi wartościami",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profil jest prowadzony wzdłuż linii lub polilinii. Profil najlepiej rysować prostopadle do początku ścieżki (np. profil na XZ, ścieżka na XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profil jest tłoczony wypukle lub wgłębnie od płaszczyzny szkicu.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Półfabrykatem jest prostopadłościan wokół wybranej bryły (plus naddatek).",
"Das Setup hat keine Operationen.":"Zamocowanie nie ma operacji.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Narzędzie frezuje po okręgach, których środek przesuwa się wzdłuż rowka. Nigdy nie skrawa na pełnej szerokości – pozwala to na duże głębokości skrawania i oszczędza frez oraz wrzeciono. Frez powinien mieć około 60 % szerokości rowka.",
"Das Werkzeug schneidet die Fläche nicht":"Narzędzie nie przecina powierzchni",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Narzędzie skrawa w kierunku wybranych ścian, aż osiągnie podane naddatki.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Narzędzie zagłębia się pionowo jak wiertło, rząd po rzędzie, do modelu plus naddatek. Siła skrawania działa wzdłuż wrzeciona: odpowiednie dla długich narzędzi, głębokich gniazd i maszyn o małej sztywności. Narzędzie musi skrawać przez środek.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Narzędzie omija te ściany z uwzględnieniem podanych odstępów bezpieczeństwa (łapy, imadło).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Narzędzie omija te ściany podczas obróbki pobliskich ścian i zachowuje odstępy bezpieczeństwa.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Pierwszy Esc anuluje tylko narzędzie lub zaznaczenie – nadmiarowy Esc nie zamyka szkicu",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"To nie jest otwór (zaokrąglenie lub czop) – kliknij wewnętrzną ścianę otworu.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"To nie jest otwór (ściana walcowa) – kliknij ścianę otworu.",
"Das ist keine WerkFab-Design-Datei.":"To nie jest plik motywu WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"To nie jest krawędź ukośna – kliknij oba końce krawędzi fazy.",
