"Deckkraft der Fenster":"Nieprzezroczystość okien",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Średnica byłaby zerowa lub ujemna – zmniejsz odległość",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Frez do gwintów pracuje w pełnym materiale: najpierw należy odsłonić czop frezowaniem (kontur 2D na zewnątrz czopa do głębokości gwintu).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Bryła nie ma obrysu na tej płaszczyźnie.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Bryła zostaje przejęta jako siatka z trójkątami wyświetlania. Sama bryła pozostaje; późniejsze zmiany bryły nie zmieniają siatki.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Bryła jest próbkowana wokół swojej pionowej osi środkowej i zapisywana jako kontur oprawki (odcinki) w bibliotece narzędzi dokumentu.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Punkt, wokół którego obraca się widok (przy swobodnej orbicie). „Pod kursorem”: miejsce na modelu, w którym zaczyna się obrót.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Promień rośnie równomiernie od początku do końca każdej wybranej krawędzi. Który koniec jest początkiem, wynika z krawędzi – w razie potrzeby zamień.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Brzeg ściany jest łańcuchem zamkniętym: przy opcji „ciągły” promień biegnie raz dookoła, bez tej opcji na każdej krawędzi osobno od promienia początkowego do końcowego.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Cięcie nie trafia w żadną bryłę – żaden materiał nie jest usuwany.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Tekst znajduje się w programie w tym miejscu jako komentarz.",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Pierwsza odległość jest mierzona na ścianie skierowanej bardziej ku górze (Z); druga odległość lub kąt dotyczy drugiej ściany. „Zamień strony” odwraca to. Krawędzie stycznie przylegające są uwzględniane.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Wybrana bryła jest półfabrykatem (np. odkuwką lub odlewem). Sama nie jest obrabiana.",
"Der große Geometriekern ist noch nicht geladen":"Pełne jądro geometryczne nie zostało jeszcze załadowane",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Trwa ładowanie pełnego jądra geometrii – ten krok zaraz sam się przeliczy",
