"Design als Datei":"Motyw jako plik",
"Design exportiert":"Projekt wyeksportowany",
"Design geladen – mit „Übernehmen“ wird es wirksam.":"Motyw wczytany – zacznie obowiązywać po kliknięciu „Zastosuj“.",
"Design nicht gefunden.":"Nie znaleziono projektu.",
"Design, Farben, Symbole, Form und Schrift in einer Datei – zum Weitergeben oder für einen anderen Rechner":"Motyw, kolory, ikony, kształt i czcionka w jednym pliku – do udostępnienia lub na inny komputer",
