"Dieses Gelenk bewegt sich mit dem gewählten (z. B. Zahnräder: Übersetzung = −Zähne₁/Zähne₂). Negative Werte drehen gegenläufig.":"Ten przegub porusza się razem z wybranym (np. koła zębate: przełożenie = −zęby₁/zęby₂). Wartości ujemne obracają w przeciwnym kierunku.",
