"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Przetłoczenie kołnierzowe {0}: zbyt wysokie dla tego otworu (otwór wstępny nie miałby średnicy)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Przetłoczenie kołnierzowe: brzeg okrągłego otworu zostaje wyciągnięty do góry w kołnierz, np. pod gwint. Średnica otworu w szkicu jest gotową średnicą wewnętrzną; w wykroju wycinany jest mniejszy otwór wstępny.",
