"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Własne skróty: otwórz menu grupy (▾) na pasku narzędzi, kliknij ⋮ przy poleceniu → „Zmień skrót klawiszowy …”.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Własne wymiary i uwagi można przeciągać myszą na arkuszu (odległość linii wymiarowej, kąt linii odniesienia, promień łuku kąta). Kliknięcie dwóch narożników = wymiar liniowy. Kliknięcie krawędzi okręgu w widoku z góry = średnica (lub promień). Kąt: najpierw wierzchołek, potem po jednym punkcie na obu ramionach. Faza: oba końce ukośnej krawędzi – daje np. 2×45°. W polu tekstowym za każdym wymiarem znajduje się dopisek, np. ±0,1, H7 lub 4×.",
