"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Frez okrągły zostawia w każdym narożniku wewnętrznym swój promień – kanciasty element współpracujący nie wejdzie wtedy do środka. Podcięcie na chwilę wjeżdża w każdy ostry narożnik wewnętrzny i wraca.{0}{1}",
