"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Najpierw kliknij ścianę na bryle, która ma być przesunięta, a potem ścianę docelową na drugiej bryle. Bryła jest obracana i przesuwana, aż pierwszy klikniony punkt znajdzie się na drugim, a ściany będą do siebie przylegać.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Najpierw kliknij krawędź na bryle, która ma być przesunięta, a potem krawędź docelową na drugiej bryle. Krawędzie proste nakładają się na siebie (środek na środek); przy krawędziach kołowych – otwór i czop – osie są skierowane zgodnie, a środki łączone.",
