"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Najpierw utwórz bryłę w trybie PROJEKT lub wstaw siatkę (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Najpierw utwórz bryłę w PROJEKT.",
