"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Kliknij ścianę bryły: jej brzeg trafi do szkicu jako kontur. Kliknięcie krawędzi rzutuje tylko tę krawędź (okręgi pozostają okręgami). Geometria rzutowana jest fioletowa.",
