"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Zamień ścianę: przenieś płaską ścianę na inną płaszczyznę – bryła rośnie lub się skraca",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Powierzchnia za oknami – obowiązuje, gdy powyżej wybrano motyw „Własny“",
