"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"Dla touchpadów: przewijanie przesuwa widok, rozsuwanie palców (lub Ctrl + kółko myszy) powiększa",
