"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Proste linie szkicu, które nie należą do żadnego profilu (także linie pomocnicze). Gięcie: linia jest środkiem strefy gięcia, a szkic jest tam wykrojem – największa część płyty pozostaje na miejscu, wszystko poza linią obraca się razem ze swoimi kołnierzami. Linia obowiązuje na całej płycie. Przetłoczenie: żebro wzdłuż linii, okrągłe w przekroju i na końcach; blacha zachowuje swoją grubość.",
