"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Zamknięte: kołnierze na dwóch sąsiednich krawędziach sięgają do dwusiecznej narożnika i zostawiają tam szczelinę. Odciążenie narożnika znajduje się tam, gdzie przecinają się strefy gięcia – w rozwinięciu i w części giętej. Kołnierz na krawędzi zakrzywionej jest w prawdziwym narożniku również ścinany ukośnie (tam bez odciążenia narożnika).",
"Geschlossene Kette {0}":"Zamknięty łańcuch {0}",
