"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Pierwsza krzywa z każdego szkicu – otwarta lub zamknięta. Krzywe są łączone powłoką (powierzchnią bez grubości).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Jeden arkusz to jeden plik. Ścieżka biegnie w odpadzie obok obrysu, odsunięta o połowę szerokości szczeliny cięcia (przy frezowaniu o połowę frezu); wycięcia występują przed obrysem swojej części, każdy kontur zaczyna się najazdem z odpadu. Włączanie M3 (laser: M3 S…), wyłączanie M5, czas przebijania jako G4. Punkt zerowy to lewy dolny róg arkusza, przy frezowaniu Z0 to górna powierzchnia blachy. Program sprawdzić przed użyciem na maszynie lub w symulatorze NC.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Każda oś osobno: kliknij krawędź, narożnik, ścianę lub otwór. Nieustawione osie pochodzą z punktu półfabrykatu.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Każda operacja jako podprogram (LBL) na końcu programu, wywołanie przez CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Każde koło szkicu jest środkiem otworu. Wiercenie następuje przeciwnie do normalnej szkicu (w głąb materiału).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Każde koło szkicu jest powtarzane z obrotem wokół środka (we współrzędnych szkicu) – koło w odległości promienia koła podziałowego daje okrąg otworów.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Każde koło szkicu staje się siatką: odstępy w X i Y szkicu (także ujemne).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Teraz punkt na drugim ramieniu.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Teraz każdy kierunek raz do oporu: przesuń, pociągnij, wciśnij, przechyl, skręć (10 s) …",
"Jetzt laden":"Pobierz teraz",
"Jetzt nach Updates suchen":"Sprawdź aktualizacje teraz",
"K-Faktor":"Współczynnik K",
"K-Faktor {0} liegt außerhalb des üblichen Bereichs 0,25 … 0,5 – der Zuschnitt weicht dann meist vom gebogenen Teil ab.":"Współczynnik K {0} jest poza typowym zakresem 0,25 … 0,5 – wykrój zwykle odbiega wtedy od wygiętej części.",
