"KONSTRUIEREN":"KONSTRUKCJA",
"KONSTRUKTION":"PROJEKT",
"KONTROLLHÖHEN ({0} × {1})":"WYSOKOŚCI KONTROLNE ({0} × {1})",
"Kalibrieren abgebrochen.":"Kalibrację przerwano.",
"Kalibrieren …":"Kalibruj …",
"Kalibrieren: einen Abstand größer als 0 angeben.":"Kalibracja: podaj odległość większą niż 0.",
"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"Kalibracja: kliknij pierwszy punkt na obrazie (Esc przerywa).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"Kalibracja: rzeczywista odległość między punktami (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Kalibracja: kliknij dwa punkty na obrazie o znanej odległości i wpisz rzeczywistą odległość – obraz otrzyma prawidłową skalę.",
"Kalibrieren: zweiten Punkt im Bild anklicken (Esc bricht ab).":"Kalibracja: kliknij drugi punkt na obrazie (Esc przerywa).",
"Kalibrierung":"Kalibracja",
"Kalibrierung zurückgesetzt.":"Kalibracja zresetowana.",
"Kamera":"Kamera",
"Kante":"Krawędź",
"Kante als Kreis projiziert":"Krawędź zrzutowana jako okrąg",
"Kante am bewegten Körper gewählt":"Wybrano krawędź na przesuwanej bryle",
"Kante im Blatt anklicken …":"Kliknij krawędź na arkuszu …",
"Kante projiziert":"Krawędź zrzutowana",
"Kante {0} (Bogen R{1}, {2} mm)":"Krawędź {0} (łuk R{1}, {2} mm)",
"Kante {0} (Kreis R{1}, {2} mm)":"Krawędź {0} (okrąg R{1}, {2} mm)",
"Kante {0} ({1} mm)":"Krawędź {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"Krawędź {0} jest za krótka na kołnierz",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Krawędź {0}: kąta gięcia powyżej 180° nie da się wykonać.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Krawędź {0}: kołnierz na krawędzi zakrzywionej – jego brzeg jest podczas gięcia ściskany o {1} % (ryzyko fałdowania); rozwinięcie jest tam przybliżeniem.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Krawędź {0}: kołnierz na krawędzi zakrzywionej – jego brzeg jest podczas gięcia rozciągany o {1} % (ryzyko pęknięć); rozwinięcie jest tam przybliżeniem.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Krawędź {0}: wymiar kołnierza {1} mm jest mniejszy niż zgięcie ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Krawędź {0}: łuk jest zbyt ciasny dla tego kołnierza",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Krawędź {0}: odsunięcia nie pozostawiają żadnego kołnierza.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Krawędź {0}: kołnierz przecina linię gięcia – zakończ go przed zgięciem za pomocą „Odsunięcie początek / koniec”",
"Kante {0}: die Lasche liegt in einer Biegezone":"Krawędź {0}: kołnierz leży w strefie gięcia",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Krawędź {0}: wycięcie należy do kołnierza, który nie istnieje.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Krawędź {0}: wycięcie w kołnierzu leży {1} mm od gięcia (mniej niż 2 × grubość blachy) – odkształca się podczas gięcia.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Krawędź {0}: wycięcie leży {1} mm obok zgięcia (mniej niż 2 × grubość blachy) – odkształci się podczas gięcia.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Krawędź {0}: wycięcie wystaje poza kołnierz.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Krawędź {0}{1}: kołnierz {2} mm jest krótszy niż 2 × grubość blachy – trudny do gięcia na prasie krawędziowej.",
"Kanten":"Krawędzie",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"Krawędzie (proste pokrywające się, okręgi współśrodkowe)",
"Kanten anklicken (erneut klicken entfernt).":"Klikaj krawędzie (ponowne kliknięcie usuwa).",
"Kanten wählen":"Wybierz krawędzie",
"Kanten wählen, die einen geschlossenen Rand bilden":"Wybierz krawędzie tworzące zamknięty brzeg",
"Kantenglättung":"Wygładzanie krawędzi",
"Kantenhöhe":"Wysokość krawędzi",
"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Puść nakładkę i wybierz „Kalibruj punkt zerowy”. Następnie wypróbuj każdy kierunek: pasek powinien się poruszać, a w spoczynku pozostawać w szarej strefie martwej.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Przesuwanie nakładki = przesuwanie, wciskanie/pociąganie = powiększanie, przechylanie i skręcanie = obracanie modelu. W szkicach tylko przesuwanie i powiększanie. SpaceMouse Pro/Enterprise: T, F, R = widok z góry, z przodu, z prawej. Jeśli nic się nie dzieje: na chwilę zamknij sterownik 3Dconnexion i połącz ponownie.",
