"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Kontury biegną wzdłuż krawędzi ciemnych obszarów. Oś środkowa biegnie środkiem kresek – odpowiednia do grawerunków i rysunków kreskowych. „Linie proste, łuki i okręgi” rozpoznaje proste krawędzie, ostre narożniki, zaokrąglenia i okręgi; „Polilinie” podążają za obrazem punkt po punkcie. Skalę można potem w razie potrzeby dostosować opcją „Kalibruj wzorzec” lub „Skaluj”.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Kontury z korekcją promienia w sterowaniu (RL/RR) są najeżdżane i opuszczane przez APPR/DEP; sterowanie samo oblicza punkt pomocniczy i korekcję",
