"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Krzywe szkicu na czole (poprzecznie do osi obrotu) napędzanym frezem wzdłuż Z (X i C poruszają się razem; Fanuc: interpolacja biegunowa G12.1). Krzywe otwarte są frezowane tam i z powrotem. Głębokość od czoła.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Krzywe szkicu leżącego wzdłuż osi obrotu są nawijane na obwód i frezowane napędzanym frezem skierowanym ku osi (Z i C poruszają się razem; Fanuc: interpolacja cylindryczna G7.1). Płaszczyzna szkicu określa kąt, pod którym leży kontur; poziome odcinki w szkicu stają się łukami wokół części. Głębokość od średnicy zewnętrznej.",
"Kurzbefehl":"Skrót",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Krótkie drogi (do odstępu przytrzymania) narzędzie pokonuje na dole z posuwem przejściowym zamiast przez wysokość wycofania – bez kontroli kolizji, dlatego wartość powinna być mała.",
