"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Kilka połączonych krawędzi liczy się jako jeden odcinek: promień biegnie od początku łańcucha do jego końca, a punkty kontrolne podaje się w % całej długości łańcucha. Oblicza to pełne jądro geometryczne.",
