"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Z punktami kontrolnymi promień przebiega przez podane wartości (położenie w % długości krawędzi). Oblicza to pełne jądro geometryczne; przy pierwszym użyciu ładuje się kilka sekund.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Sondą 3D nie można skrawać",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Porównaj z gotową częścią: zielony = na wymiar, niebieski = materiał pozostały, czerwony = za głęboko",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Przesuń mysz obok konturu (strona określa kierunek) · Esc kończy",
"Mit diesem Werkzeug kann nicht gefräst werden":"Tym narzędziem nie można frezować",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Z gwintownikiem używać tylko cyklu „Gwintowanie” – cykl wiercenia złamałby go",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Przy kilku wcięciach głębokość gwintu jest frezowana etapami, z których każdy usuwa mniej więcej tyle samo – oszczędza małe frezy do gwintów i twarde materiały. Przejście wygładzające przejeżdża ostatnią ścieżkę jeszcze raz bez wcięcia.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Przy włączonych „Cyklach wiercenia“ w programie NC wyprowadzane są cykle sterowania (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85); w przeciwnym razie ruchy rozpisane.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Z opcją „Zachowaj oryginał” oryginał i jego odbicie stają się jedną siatką; punkty na płaszczyźnie odbicia są łączone – otwarta połowa staje się w ten sposób zamkniętą częścią.",
