"Nichts gewählt – „Auswählen“, dann Flächen oder Kanten im Modell anklicken.":"Nic nie wybrano – „Wybierz“, a następnie kliknij ściany lub krawędzie w modelu.",
"Nichts geändert: Die Nachbarflächen schließen diese Lücke nicht – zusammengehörige Flächen gemeinsam wählen (z. B. Wand und Boden einer Tasche)":"Nic nie zmieniono: powierzchnie sąsiednie nie zamykają tej szczeliny – wybrać razem powierzchnie, które do siebie należą (np. ścianę i dno kieszeni)",
