"Noch kein Dreh-Setup: „Neues Setup“ → Bearbeitung „Drehen“ wählen.":"Brak zamocowania do toczenia: „Nowe zamocowanie” → wybierz obróbkę „Toczenie”.",
"Noch kein Fräs-Setup vorhanden.":"Brak zamocowania do frezowania.",
"Noch kein Körper gewählt – bis dahin gilt die relative Quadergröße.":"Nie wybrano jeszcze bryły – do tego czasu obowiązuje względny rozmiar prostopadłościanu.",
"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"Brak jeszcze bryły – najpierw zamodelować w KONSTRUKCJI.",
