"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"Brak komentarzy. Przyciskiem + dodaj notatki do projektu.",
"Noch keine Operation":"Brak operacji",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Brak szablonów. Szablon zapisuje strategie ze wszystkimi ustawieniami (narzędzie, dane skrawania, wysokości, przejścia, powiązanie) do ponownego użycia w innych zamocowaniach i projektach.",
"Noch keine Werkzeuge im Dokument.":"W dokumencie nie ma jeszcze narzędzi.",
"Noch keine. Geometrie wählen und oben unter ABHÄNGIGKEITEN ein Werkzeug anklicken.":"Brak. Wybierz geometrię i kliknij narzędzie powyżej w sekcji WIĄZANIA.",
