"Nur ASCII-Zeichen":"Tylko znaki ASCII",
"Nur Außenkonturen":"Tylko kontury zewnętrzne",
"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Jako cykl sterowania działają tylko kontury zewnętrzne (czopy)",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Tylko średnica (kształt jak to narzędzie)",
"Nur Innenkonturen (Öffnungen)":"Tylko kontury wewnętrzne (otwory)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Jako cykl sterowania działają tylko kieszenie prostokątne i kołowe",
"Nur Skizze":"Tylko szkic",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Obrabiaj tylko to, co większy frez zostawił w narożnikach.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Przejeżdżaj tylko te miejsca konturu, do których nie dotarł większy frez (narożniki wewnętrzne, wąskie miejsca). Bez łuków wejścia/wyjścia, mostków i przejść wykańczających; korekcja w komputerze.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Tylko tam, gdzie narzędzie referencyjne nie dotarło: obszary płaskie równolegle, strome jako linia wodna. Przy narzędziu z listy liczy się też jego kształt – na przykład to, co frez toroidalny zostawia w wyobleniach.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Tylko płaskie ściany mogą służyć jako płaszczyzna szkicu.",
"Nur ebene Flächen können extrudiert werden":"Wyciągać można tylko ściany płaskie",
"Nur ebene Flächen lassen sich ersetzen":"Zastępować można tylko ściany płaskie",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Przesuwać można tylko ściany płaskie i walcowe (otwory, czopy)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Tylko płaskie ściany skierowane w górę, ku narzędziu (poziome w tym zamocowaniu).",
"Nur für Außen-Drehmeißel":"Tylko dla zewnętrznych noży tokarskich",
"Nur in Operationen verwendete":"Tylko użyte w operacjach",
"Nur in diesem Projekt":"Tylko w tym projekcie",
"Nur mit Korrektur „Im Rechner“.":"Tylko z korekcją „W komputerze“.",
"Nur stärkste Achse":"Tylko dominująca oś",
"Nut":"Rowek",
"Nut angetrieben":"Rowek narzędziem napędzanym",
"Nut angetrieben (C-Achse)":"Rowek napędzany (oś C)",
"Nut liegt nicht am Teil":"Rowek nie leży na części",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Rowek wzdłuż osi obrotu (np. rowek wpustowy) napędzanym frezem skierowanym ku osi; wrzeciono główne trzyma część jako oś C. Szerokość rowka = Ø freza. Początek/koniec Z w Z modelu; jeśli rowek sięga do czoła, frez wjeżdża od przodu, w przeciwnym razie zagłębia się na początku. Głębokość od średnicy zewnętrznej.",
"Nutbreite bei Linien":"Szerokość rowka przy liniach",
