"Offene Flächen":"Ściany otwarte",
"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Otwarte krawędzie są wyświetlane na czerwono. „Napraw” zamyka dziury.",
"Offene Linie in einer Skizze wählen":"Wybierz otwartą linię w szkicu",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Krzywe otwarte lub zamknięte są wyciągane prostopadle do szkicu – powstaje powierzchnia (ścianka bez grubości). Opcja „Pogrubienie” lub „Zszycie” zamienia ją w bryłę.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Krzywe otwarte lub zamknięte są obracane wokół osi – powstaje powierzchnia, a nie bryła.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Bez własnego klawisza obowiązuje domyślny „{0}”.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Bez opcji „Modelowany” gwint jest tylko przedstawiany (szybko). Po jej włączeniu kształt gwintu jest faktycznie wycinany, np. do druku 3D. Otwór pod M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP toczenie",
"Okuma OSP-M Fräsen":"Okuma OSP-M frezowanie",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 nie jadą tam do współrzędnych maszyny (G53 znosi korekcję długości narzędzia) – odjazd na wysokość bezpieczną, nie wypisano jazdy referencyjnej XY",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: nie wypisano funkcji wygładzania (G5.1 jest z Fanuc) – ustaw Hi-Cut/Super-NURBS na maszynie",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: korekcja+narzędzie+ostrze (np. 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (wszystkie funkcje)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: wszystkie funkcje. Jądro Rust (truck, eksperymentalne): bryły podstawowe, wyciągnięcie, obrót, otwór, szyk, lustro, przesunięcie, skalowanie, łączenie i eksport STEP – pozostałe operacje są oznaczane jako „jeszcze nieobsługiwane”.",
