"Positiv = nach außen (mehr Material), negativ = nach innen. Ebene Flächen verschieben sich; bei einer Bohrung oder einem Zapfen ändert sich der Radius um den Abstand – eine Bohrung wird mit positivem Abstand enger.":"Dodatnia = na zewnątrz (więcej materiału), ujemna = do wewnątrz. Ściany płaskie się przesuwają; w otworze lub czopie promień zmienia się o tę odległość – otwór przy dodatniej odległości staje się węższy.",
"Positiver Abstand = in Richtung der Skizzennormalen. Taschen: Ausschneiden mit negativem Abstand.":"Odległość dodatnia = w kierunku normalnej szkicu. Kieszenie: wycięcie z odległością ujemną.",
