"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"Rzutuj (J): kliknij ścianę lub krawędź bryły – jej rzut trafi do szkicu",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"Rzutowanie krawędzi i ścian wymaga bryły objętościowej standardowego jądra – obrys bryły i krzywe przecięcia działają także dla siatek.",
