"Prägen braucht einen Körper.":"Wytłaczanie wymaga bryły.",
"Prägung":"Tłoczenie",
"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Tłoczenie {0}: kontur jest węższy niż 2 × grubość blachy – nie powstaje wnęka.",
"Prägung {0}: lässt sich so nicht formen":"Tłoczenie {0}: nie da się tak uformować",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Tłoczenie {0}: {1} mm to więcej niż 3 × grubość blachy – przy pionowej ściance blacha pęka.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Tłoczenie: kontur nie jest wycinany, lecz wytłaczany z płyty na podaną wysokość. Pogłębienie tłoczone: brzeg okrągłego otworu jest wytłaczany w stożek 90° – pod śruby z łbem stożkowym w cienkiej blasze (− w dół: śruba od góry).",
