"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Kieszeń na obwodzie z zamkniętych konturów szkicu leżącego wzdłuż osi toczenia (kontury wewnętrzne pozostają jako wyspy). Szkic jest nawijany na średnicę; napędzana frezarka palcowa skierowana do osi usuwa materiał od środka na zewnątrz (Z i C poruszają się razem; Fanuc: interpolacja walcowa G7.1). Frez wchodzi po rampie wzdłuż najbardziej wewnętrznego pierścienia.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Kieszeń w czole z zamkniętych konturów szkicu (kontury wewnętrzne pozostają jako wyspy), napędzanym frezem trzpieniowym wzdłuż Z. Usuwanie materiału idzie od środka na zewnątrz; frez wchodzi po rampie wzdłuż najbardziej wewnętrznej ścieżki i pozostaje na dole w obrębie jednego poziomu. X i C poruszają się razem (Fanuc: interpolacja biegunowa G12.1). Głębokość od czoła.",
