"Vermeiden":"Unikaj",
"Vernetzung fehlgeschlagen:":"Tworzenie siatki nie powiodło się:",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Naprawdę przelicza dwie zamknięte siatki ze sobą: ściany leżące wewnątrz znikają, krawędzie przecięcia są siatkowane na nowo. Obliczenia obejmują tylko obszar, w którym obie siatki mogą się spotkać – duża siatka z małym zabiegiem jest więc przetwarzana szybko. Jeśli dwie duże siatki pokrywają się całkowicie, najpierw użyj „Redukuj”.",
