"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Nawija krzywe szkicu na walec: X pozostaje X, odległość poprzeczna do osi staje się łukiem na Ø rozwinięcia (obrót A). Szkic musi leżeć równolegle do osi A, np. na płaszczyźnie stycznej. Frezowanie odbywa się na stałej głębokości pod powierzchnią części – do grawerunków, napisów i rowków wokół części.",
