"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Układaj jedne w drugich” umieszcza rozwinięcia w lukach i zatokach sąsiednich elementów oraz w ich wycięciach (bez obrotu o 90°, tylko odwrócone o 180°); odstęp nigdy nie jest zmniejszany. Bez zaznaczenia są układane w rzędach według otaczającego je prostokąta. Opcja „Szkic + bryły” tworzy płaskie bryły o grubości blachy, które w wytwarzaniu można wycinać konturem 2D.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"„Wewnątrz/Na zewnątrz” wymaga zamkniętych konturów – otwarte krzywe frezować opcją „Na krzywej”",
