"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ Logika programu (JavaScript) nie jest wykonywana: funkcje specjalne, 4./5. oś, cykle pomiarowe i opcje maszyny należy sprawdzić w edytorze postprocesora.",
